function c(t){return Array.isArray(t)?t:Array.isArray(t.items)?t.items:Array.isArray(t.data)?t.data:[]}function f(t){if(!Array.isArray(t))return typeof t.total=="number"?t.total:void 0}async function l(t,I){const a=Math.min(Math.max(1,1e3),1e3),A=200,r=[];let n=0;for(let i=0;i<A;i+=1){const e=await t({skip:n,limit:a}),o=c(e);if(r.push(...o),o.length<a)break;const s=f(e);if(typeof s=="number"&&r.length>=s)break;n+=a}return r}export{l as f};
